INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Doodle Devil: 3volution', 'While Doodle God was busy creating the universe, Doodle Devil was also having some fun. The same addictive, puzzle game play that made Doodle God a hit is back but with an evil twist. Discover the seven deadly sins and watch as the world crumbles at your fingertips as you create thousands of dastardly deeds. Combine fire, earth, wind & air to create demons, beasts, zombies... and much more. Being bad has never been so much fun!' FROM games WHERE igdb_id = 147737 ON CONFLICT (game_id, language_code) DO NOTHING;
